\[
\boxed{
\delta_{\mathcal C}\Phi_{n+1}
=
\ln
\left(
\frac{
\nu_{n,\alpha,H}
}{
\nu_{n,\alpha,L}
}
\right).
}
\]
Therefore,
\[
\boxed{
\delta_{\mathcal C}\Phi_{n+1}
\geq0.
}
\]

